-- Postgres baseline schema. Replaces the 131 MariaDB migrations archived under
-- db/migration-mariadb-archive/ (kept for history only, not on Flyway's classpath).
-- Generated by applying all of them against a throwaway MariaDB instance and translating
-- the resulting end-state schema to Postgres syntax -- see PR description for the process.


-- ============ TABLES ============

CREATE TABLE "annotations" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "book_id" BIGINT NOT NULL,
    "cfi" VARCHAR(1000) NOT NULL,
    "text" VARCHAR(5000) NOT NULL,
    "color" VARCHAR(20) DEFAULT NULL,
    "style" VARCHAR(50) DEFAULT NULL,
    "note" VARCHAR(5000) DEFAULT NULL,
    "chapter_title" VARCHAR(500) DEFAULT NULL,
    "version" BIGINT NOT NULL DEFAULT 0,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "app_migration" (
    "migration_key" VARCHAR(100) NOT NULL,
    "executed_at" TIMESTAMP NOT NULL,
    "description" TEXT DEFAULT NULL,
    PRIMARY KEY ("migration_key")
);

CREATE TABLE "app_settings" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "name" VARCHAR(255) NOT NULL,
    "val" TEXT DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "audit_log" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT DEFAULT NULL,
    "username" VARCHAR(255) NOT NULL,
    "action" VARCHAR(100) NOT NULL,
    "entity_type" VARCHAR(100) DEFAULT NULL,
    "entity_id" BIGINT DEFAULT NULL,
    "description" VARCHAR(1024) NOT NULL,
    "ip_address" VARCHAR(45) DEFAULT NULL,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "country_code" CHAR(2) DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "author" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "name" VARCHAR(255) DEFAULT NULL,
    "description" TEXT DEFAULT NULL,
    "asin" VARCHAR(20) DEFAULT NULL,
    "name_locked" BOOLEAN NOT NULL DEFAULT false,
    "description_locked" BOOLEAN NOT NULL DEFAULT false,
    "asin_locked" BOOLEAN NOT NULL DEFAULT false,
    "photo_locked" BOOLEAN NOT NULL DEFAULT false,
    PRIMARY KEY ("id")
);

CREATE TABLE "book" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "library_id" BIGINT NOT NULL,
    "library_path_id" BIGINT DEFAULT NULL,
    "added_on" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "similar_books_json" TEXT DEFAULT NULL,
    "metadata_match_score" DOUBLE PRECISION DEFAULT NULL,
    "read_status" VARCHAR(20) DEFAULT 'UNREAD',
    "deleted" BOOLEAN DEFAULT false,
    "deleted_at" TIMESTAMP DEFAULT NULL,
    "metadata_updated_at" TIMESTAMP DEFAULT NULL,
    "metadata_for_write_updated_at" TIMESTAMP DEFAULT NULL,
    "book_cover_hash" VARCHAR(20) DEFAULT NULL,
    "is_physical" BOOLEAN NOT NULL DEFAULT false,
    "audiobook_cover_hash" VARCHAR(20) DEFAULT NULL,
    "scanned_on" TIMESTAMP DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "book_award" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "book_id" BIGINT NOT NULL,
    "name" VARCHAR(255) NOT NULL,
    "awarded_at" TIMESTAMP NOT NULL,
    "category" VARCHAR(255) NOT NULL,
    "designation" VARCHAR(255) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "book_file" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "book_id" BIGINT NOT NULL,
    "file_name" VARCHAR(1000) NOT NULL,
    "file_sub_path" VARCHAR(512) NOT NULL,
    "file_size_kb" BIGINT DEFAULT NULL,
    "initial_hash" VARCHAR(128) DEFAULT NULL,
    "current_hash" VARCHAR(128) DEFAULT NULL,
    "description" TEXT DEFAULT NULL,
    "added_on" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "is_book" BOOLEAN DEFAULT false,
    "book_type" VARCHAR(32) DEFAULT NULL,
    "archive_type" VARCHAR(255) DEFAULT NULL,
    "alt_format_current_hash" VARCHAR(128) GENERATED ALWAYS AS (case when is_book then current_hash end) STORED,
    "is_folder_based" BOOLEAN NOT NULL DEFAULT false,
    "duration_seconds" BIGINT DEFAULT NULL,
    "bitrate" INTEGER DEFAULT NULL,
    "sample_rate" INTEGER DEFAULT NULL,
    "channels" INTEGER DEFAULT NULL,
    "codec" VARCHAR(50) DEFAULT NULL,
    "chapter_count" INTEGER DEFAULT NULL,
    "chapters_json" TEXT DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "book_marks" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "book_id" BIGINT NOT NULL,
    "cfi" VARCHAR(1000) DEFAULT NULL,
    "title" VARCHAR(255) DEFAULT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "color" VARCHAR(7) DEFAULT NULL,
    "notes" VARCHAR(2000) DEFAULT NULL,
    "priority" INTEGER DEFAULT NULL,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "version" BIGINT NOT NULL DEFAULT 1,
    "position_ms" BIGINT DEFAULT NULL,
    "track_index" INTEGER DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "book_metadata" (
