    "series_name" VARCHAR(1000) DEFAULT NULL,
    "series_number" DOUBLE PRECISION DEFAULT NULL,
    "series_total" INTEGER DEFAULT NULL,
    "all_fields_locked" BOOLEAN DEFAULT false,
    "title_locked" BOOLEAN DEFAULT false,
    "authors_locked" BOOLEAN DEFAULT false,
    "categories_locked" BOOLEAN DEFAULT false,
    "subtitle_locked" BOOLEAN DEFAULT false,
    "publisher_locked" BOOLEAN DEFAULT false,
    "published_date_locked" BOOLEAN DEFAULT false,
    "description_locked" BOOLEAN DEFAULT false,
    "isbn_13_locked" BOOLEAN DEFAULT false,
    "isbn_10_locked" BOOLEAN DEFAULT false,
    "page_count_locked" BOOLEAN DEFAULT false,
    "thumbnail_locked" BOOLEAN DEFAULT false,
    "language_locked" BOOLEAN DEFAULT false,
    "cover_locked" BOOLEAN DEFAULT false,
    "rating_locked" BOOLEAN DEFAULT false,
    "review_count_locked" BOOLEAN DEFAULT false,
    "series_name_locked" BOOLEAN DEFAULT false,
    "series_number_locked" BOOLEAN DEFAULT false,
    "series_total_locked" BOOLEAN DEFAULT false,
    "amazon_rating" DOUBLE PRECISION DEFAULT NULL,
    "amazon_review_count" INTEGER DEFAULT NULL,
    "goodreads_rating" DOUBLE PRECISION DEFAULT NULL,
    "goodreads_review_count" INTEGER DEFAULT NULL,
    "amazon_rating_locked" BOOLEAN DEFAULT false,
    "amazon_review_count_locked" BOOLEAN DEFAULT false,
    "goodreads_rating_locked" BOOLEAN DEFAULT false,
    "goodreads_review_count_locked" BOOLEAN DEFAULT false,
    "asin" VARCHAR(20) DEFAULT NULL,
    "asin_locked" BOOLEAN DEFAULT false,
    "hardcover_rating" DOUBLE PRECISION DEFAULT NULL,
    "hardcover_review_count" INTEGER DEFAULT NULL,
    "hardcover_rating_locked" BOOLEAN DEFAULT false,
    "hardcover_review_count_locked" BOOLEAN DEFAULT false,
    "goodreads_id" VARCHAR(100) DEFAULT NULL,
    "hardcover_id" VARCHAR(512) DEFAULT NULL,
    "google_id" VARCHAR(100) DEFAULT NULL,
    "goodreads_id_locked" BOOLEAN DEFAULT false,
    "hardcover_id_locked" BOOLEAN DEFAULT false,
    "google_id_locked" BOOLEAN DEFAULT false,
    "comicvine_id" VARCHAR(100) DEFAULT NULL,
    "comicvine_id_locked" BOOLEAN DEFAULT false,
    "reviews_locked" BOOLEAN DEFAULT false,
    "moods_locked" BOOLEAN DEFAULT false,
    "tags_locked" BOOLEAN DEFAULT false,
    "embedding_vector" TEXT DEFAULT NULL,
    "embedding_updated_at" TIMESTAMP DEFAULT NULL,
    "search_text" TEXT DEFAULT NULL,
    "hardcover_book_id" VARCHAR(100) DEFAULT NULL,
    "hardcover_book_id_locked" BOOLEAN DEFAULT false,
    "lubimyczytac_id" VARCHAR(100) DEFAULT NULL,
    "lubimyczytac_rating" DOUBLE PRECISION DEFAULT NULL,
    "lubimyczytac_id_locked" BOOLEAN DEFAULT false,
    "lubimyczytac_rating_locked" BOOLEAN DEFAULT false,
    "ranobedb_id" VARCHAR(100) DEFAULT NULL,
    "ranobedb_rating" DOUBLE PRECISION DEFAULT NULL,
    "ranobedb_id_locked" BOOLEAN DEFAULT false,
    "ranobedb_rating_locked" BOOLEAN DEFAULT false,
    "audiobook_cover_updated_on" TIMESTAMP DEFAULT NULL,
    "audible_id" VARCHAR(100) DEFAULT NULL,
    "audible_rating" DOUBLE PRECISION DEFAULT NULL,
    "audible_review_count" INTEGER DEFAULT NULL,
    "audible_id_locked" BOOLEAN DEFAULT false,
    "audible_rating_locked" BOOLEAN DEFAULT false,
    "audible_review_count_locked" BOOLEAN DEFAULT false,
    "audiobook_cover_locked" BOOLEAN DEFAULT false,
    "narrator_locked" BOOLEAN DEFAULT false,
    "abridged_locked" BOOLEAN DEFAULT false,
    "narrator" VARCHAR(500) DEFAULT NULL,
    "abridged" BOOLEAN DEFAULT NULL,
    "age_rating" INTEGER DEFAULT NULL,
    "content_rating" VARCHAR(20) DEFAULT NULL,
    "age_rating_locked" BOOLEAN NOT NULL DEFAULT false,
    "content_rating_locked" BOOLEAN NOT NULL DEFAULT false,
    PRIMARY KEY ("book_id")
);

CREATE TABLE "book_metadata_author_mapping" (
