CREATE TABLE "new_pdf_viewer_preference" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "book_id" BIGINT NOT NULL,
    "spread" VARCHAR(16) DEFAULT NULL,
    "view_mode" VARCHAR(16) DEFAULT NULL,
    "fit_mode" VARCHAR(16) DEFAULT NULL,
    "scroll_mode" VARCHAR(16) DEFAULT NULL,
    "background_color" VARCHAR(16) DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "oidc_group_mapping" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "oidc_group_claim" VARCHAR(255) NOT NULL,
    "is_admin" BOOLEAN NOT NULL DEFAULT false,
    "permissions" TEXT DEFAULT NULL,
    "library_ids" TEXT DEFAULT NULL,
    "description" VARCHAR(500) DEFAULT NULL,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE "oidc_session" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "oidc_subject" VARCHAR(255) NOT NULL,
    "oidc_issuer" VARCHAR(512) NOT NULL,
    "oidc_session_id" VARCHAR(255) DEFAULT NULL,
    "id_token_hint" TEXT DEFAULT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "last_refreshed_at" TIMESTAMP DEFAULT NULL,
    "revoked" BOOLEAN DEFAULT false,
    PRIMARY KEY ("id")
);

CREATE TABLE "opds_user" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "username" VARCHAR(255) NOT NULL,
    "password" VARCHAR(255) NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE "opds_user_v2" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "username" VARCHAR(100) NOT NULL,
    "password_hash" VARCHAR(255) NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "sort_order" VARCHAR(20) NOT NULL DEFAULT 'RECENT',
    PRIMARY KEY ("id")
);

CREATE TABLE "pdf_annotations" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "book_id" BIGINT NOT NULL,
    "data" TEXT NOT NULL,
    "version" BIGINT NOT NULL DEFAULT 0,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "pdf_viewer_preference" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "book_id" BIGINT NOT NULL,
    "zoom" VARCHAR(64) DEFAULT NULL,
    "spread" VARCHAR(64) DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "public_book_review" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "metadata_provider" VARCHAR(255) NOT NULL,
    "book_id" BIGINT NOT NULL,
    "reviewer_name" VARCHAR(512) DEFAULT NULL,
    "title" VARCHAR(512) DEFAULT NULL,
    "rating" DOUBLE PRECISION DEFAULT NULL,
    "date" TIMESTAMP DEFAULT NULL,
    "body" TEXT DEFAULT NULL,
    "country" VARCHAR(255) DEFAULT NULL,
    "spoiler" BOOLEAN DEFAULT NULL,
    "followers_count" INTEGER DEFAULT NULL,
    "text_reviews_count" INTEGER DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "reading_sessions" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "book_id" BIGINT NOT NULL,
    "book_type" VARCHAR(10) NOT NULL,
    "start_time" TIMESTAMP NOT NULL,
    "end_time" TIMESTAMP NOT NULL,
    "duration_seconds" INTEGER NOT NULL,
    "start_progress" DOUBLE PRECISION DEFAULT NULL,
    "end_progress" DOUBLE PRECISION DEFAULT NULL,
    "progress_delta" DOUBLE PRECISION DEFAULT NULL,
    "start_location" VARCHAR(500) DEFAULT NULL,
    "end_location" VARCHAR(500) DEFAULT NULL,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "duration_formatted" VARCHAR(50) DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "refresh_token" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "token" VARCHAR(512) NOT NULL,
    "expiry_date" TIMESTAMP(6) NOT NULL,
    "revoked" BOOLEAN NOT NULL DEFAULT false,
    "revocation_date" TIMESTAMP(6) DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "shelf" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "name" VARCHAR(255) NOT NULL,
    "sort" VARCHAR(255) DEFAULT NULL,
    "icon" VARCHAR(64) DEFAULT NULL,
    "icon_type" VARCHAR(255) DEFAULT NULL,
    "is_public" BOOLEAN NOT NULL DEFAULT false,
    PRIMARY KEY ("id")
);

CREATE TABLE "tag" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "name" VARCHAR(255) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "task_cron_configuration" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "task_type" VARCHAR(100) NOT NULL,
    "cron_expression" VARCHAR(100) NOT NULL,
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "created_by" BIGINT NOT NULL DEFAULT -1,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE "tasks" (
    "id" VARCHAR(36) NOT NULL,
    "type" VARCHAR(50) NOT NULL,
    "status" VARCHAR(50) NOT NULL,
    "user_id" BIGINT NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT NULL,
    "completed_at" TIMESTAMP DEFAULT NULL,
    "progress_percentage" INTEGER DEFAULT NULL,
    "message" TEXT DEFAULT NULL,
    errordetails TEXT DEFAULT NULL,
    "task_options" TEXT DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "user_book_file_progress" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "book_file_id" BIGINT NOT NULL,
    "position_data" VARCHAR(1000) DEFAULT NULL,
    "position_href" VARCHAR(1000) DEFAULT NULL,
    "progress_percent" DOUBLE PRECISION DEFAULT NULL,
    "last_read_time" TIMESTAMP DEFAULT NULL,
    "tts_position_cfi" VARCHAR(1000) DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "user_book_progress" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "book_id" BIGINT NOT NULL,
    "last_read_time" TIMESTAMP DEFAULT NULL,
    "pdf_progress" INTEGER DEFAULT NULL,
    "epub_progress" VARCHAR(1000) DEFAULT NULL,
    "pdf_progress_percent" DOUBLE PRECISION DEFAULT NULL,
    "epub_progress_percent" DOUBLE PRECISION DEFAULT NULL,
    "cbx_progress" INTEGER DEFAULT NULL,
    "cbx_progress_percent" DOUBLE PRECISION DEFAULT NULL,
    "read_status" VARCHAR(20) DEFAULT NULL,
    "date_finished" TIMESTAMP DEFAULT NULL,
    "koreader_progress" VARCHAR(1000) DEFAULT NULL,
    "koreader_progress_percent" DOUBLE PRECISION DEFAULT NULL,
    "koreader_device" VARCHAR(100) DEFAULT NULL,
    "koreader_device_id" VARCHAR(100) DEFAULT NULL,
    "koreader_last_sync_time" TIMESTAMP DEFAULT NULL,
    "kobo_progress_percent" DOUBLE PRECISION DEFAULT NULL,
    "kobo_location" VARCHAR(1000) DEFAULT NULL,
    "kobo_location_type" VARCHAR(50) DEFAULT NULL,
    "kobo_location_source" VARCHAR(512) DEFAULT NULL,
    "kobo_progress_received_time" TIMESTAMP DEFAULT NULL,
    "kobo_status_sent_time" TIMESTAMP DEFAULT NULL,
    "read_status_modified_time" TIMESTAMP DEFAULT NULL,
    "kobo_progress_sent_time" TIMESTAMP DEFAULT NULL,
    "personal_rating" SMALLINT DEFAULT NULL,
    "epub_progress_href" VARCHAR(1000) DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "user_content_restriction" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "restriction_type" VARCHAR(20) NOT NULL,
    "mode" VARCHAR(15) NOT NULL,
    "value" VARCHAR(255) NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE "user_email_provider_preference" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "default_provider_id" BIGINT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "user_library_mapping" (
    "user_id" BIGINT NOT NULL,
    "library_id" BIGINT NOT NULL,
    PRIMARY KEY ("user_id", "library_id")
);

CREATE TABLE "user_permissions" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "permission_upload" BOOLEAN NOT NULL DEFAULT false,
    "permission_download" BOOLEAN NOT NULL DEFAULT false,
    "permission_edit_metadata" BOOLEAN NOT NULL DEFAULT false,
    "permission_manipulate_library" BOOLEAN NOT NULL DEFAULT false,
    "permission_admin" BOOLEAN NOT NULL DEFAULT false,
    "permission_email_book" BOOLEAN NOT NULL DEFAULT true,
    "permission_delete_book" BOOLEAN NOT NULL DEFAULT false,
    "permission_sync_koreader" BOOLEAN NOT NULL DEFAULT false,
    "permission_sync_kobo" BOOLEAN NOT NULL DEFAULT false,
    "permission_access_opds" BOOLEAN NOT NULL DEFAULT false,
    "permission_manage_metadata_config" BOOLEAN NOT NULL DEFAULT false,
    "permission_access_bookdrop" BOOLEAN NOT NULL DEFAULT false,
    "permission_access_library_stats" BOOLEAN NOT NULL DEFAULT false,
    "permission_access_user_stats" BOOLEAN NOT NULL DEFAULT false,
    "permission_access_task_manager" BOOLEAN NOT NULL DEFAULT false,
    "permission_manage_global_preferences" BOOLEAN NOT NULL DEFAULT false,
    "permission_manage_icons" BOOLEAN NOT NULL DEFAULT false,
    "permission_demo_user" BOOLEAN NOT NULL DEFAULT false,
    "permission_bulk_auto_fetch_metadata" BOOLEAN NOT NULL DEFAULT false,
    "permission_bulk_custom_fetch_metadata" BOOLEAN NOT NULL DEFAULT false,
    "permission_bulk_edit_metadata" BOOLEAN NOT NULL DEFAULT false,
    "permission_bulk_regenerate_cover" BOOLEAN NOT NULL DEFAULT false,
    "permission_move_organize_files" BOOLEAN NOT NULL DEFAULT false,
    "permission_bulk_lock_unlock_metadata" BOOLEAN NOT NULL DEFAULT false,
    "permission_bulk_reset_booklore_read_progress" BOOLEAN NOT NULL DEFAULT false,
    "permission_bulk_reset_koreader_read_progress" BOOLEAN NOT NULL DEFAULT false,
    "permission_bulk_reset_book_read_status" BOOLEAN NOT NULL DEFAULT false,
    "permission_manage_fonts" BOOLEAN NOT NULL DEFAULT false,
    PRIMARY KEY ("id")
);

CREATE TABLE "user_settings" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "user_id" BIGINT NOT NULL,
    "setting_key" VARCHAR(100) NOT NULL,
    "setting_value" TEXT NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE "users" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "username" VARCHAR(255) NOT NULL,
    "password_hash" VARCHAR(255) NOT NULL,
    "is_default_password" BOOLEAN NOT NULL DEFAULT true,
    "name" VARCHAR(255) NOT NULL,
    "email" VARCHAR(255) DEFAULT NULL,
    "book_preferences" TEXT DEFAULT NULL,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "provisioning_method" VARCHAR(50) DEFAULT NULL,
    "oidc_subject" VARCHAR(255) DEFAULT NULL,
    "oidc_issuer" VARCHAR(512) DEFAULT NULL,
    "avatar_url" VARCHAR(1024) DEFAULT NULL,
    PRIMARY KEY ("id")
);

