-- ============ COLUMN COMMENTS ============

COMMENT ON COLUMN "app_migration"."migration_key" IS 'Unique identifier for the migration';
COMMENT ON COLUMN "app_migration"."executed_at" IS 'When the migration was executed';
COMMENT ON COLUMN "app_migration"."description" IS 'Optional description of what the migration did';

-- ============ updated_at TRIGGER TABLES (manual) ============
-- book_notes, bookdrop_file, koreader_user, magic_shelf, oidc_group_mapping, opds_user_v2, task_cron_configuration, user_settings

-- ============ updated_at TRIGGER ============

CREATE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_book_notes_updated_at BEFORE UPDATE ON "book_notes" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_bookdrop_file_updated_at BEFORE UPDATE ON "bookdrop_file" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_koreader_user_updated_at BEFORE UPDATE ON "koreader_user" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_magic_shelf_updated_at BEFORE UPDATE ON "magic_shelf" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_oidc_group_mapping_updated_at BEFORE UPDATE ON "oidc_group_mapping" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_opds_user_v2_updated_at BEFORE UPDATE ON "opds_user_v2" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_task_cron_configuration_updated_at BEFORE UPDATE ON "task_cron_configuration" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_user_settings_updated_at BEFORE UPDATE ON "user_settings" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
